    const carta = (tipo) => ({ id: 'k' + numeros[k++], tipo });

    this.jugadores = ids.map((id) => ({ id, mano: [], vivo: true, conectado: true, salio: false, stats: { jugadas: 0, negadas: 0, desactivados: 0, robos: 0 } }));
    const mazoBase = this.mezclar(base.map(carta));
